const headers={"content-type":"application/json; charset=utf-8","cache-control":"no-store"};
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers});
const clean=(v,n=10000)=>String(v??"").slice(0,n);
const parse=async r=>{try{return await r.json()}catch{return null}};
const norm=(v)=>String(v??"").toLowerCase();
const asTemplates=(v)=>{try {const p=JSON.parse(v||"[]");if(Array.isArray(p))return {full:p.slice(0,4),maintenance:p.slice(4,8).length?p.slice(4,8):p.slice(0,4)};if(p&&typeof p==="object")return {full:p.full||p.voll||p.bausteine||[],maintenance:p.maintenance||p.aufrechterhaltung||p.bausteine||p.full||[]};}catch{}return {full:v?[String(v)]:[],maintenance:v?[String(v)]:[]}};
const modeOf=a=>/vollaudit|erstzertifizierung/i.test(a.bezeichnung||"")||(!/aufrechterhaltung/i.test(a.bezeichnung||"")&&Number(String(a.auditdatum||"").slice(0,4))===2025)?"Vollaudit":"Aufrechterhaltungsaudit";
const statusOf=s=>{let n=norm(s).trim();return n==="ok"?"OK":n==="nc"?"NC":n==="e"?"E":n==="empfehlung"?"E":n==="nichtkonformität"?"NC":""};
async function api(req,env,url,ctx){
 if(!env.DB)return json({error:"D1-Binding DB fehlt"},503);
 // Require Cloudflare Access authentication for each API request.
 // ctx.access is supplied by Cloudflare after authentication.
 if(!ctx?.access)return json({error:"Anmeldung über Cloudflare Access erforderlich"},403);
 try{
   const identity=await ctx.access.getIdentity();
   if(!identity?.email)return json({error:"Keine bestätigte Benutzeridentität"},403);
 }catch{return json({error:"Access-Identität konnte nicht geprüft werden"},403)}
 const p=url.pathname;
 try{
 if(p==="/api/health")return json({ok:true,database:true});
 if(/^\/api\/audits\/\d+\/report-intro$/.test(p)){
  const auditId=Number(p.split("/")[3]);
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS aw_berichttexte (audit_id INTEGER PRIMARY KEY, einleitung TEXT NOT NULL, aktualisiert_am TEXT DEFAULT (datetime('now')))").run();
  if(req.method==="GET"){const row=await env.DB.prepare("SELECT einleitung FROM aw_berichttexte WHERE audit_id=?").bind(auditId).first();return json({intro:row?.einleitung??null})}
  if(req.method==="PUT"){const d=await parse(req);if(typeof d?.intro!=="string"||d.intro.length>12000)return json({error:"Ungültiger Berichtstext"},400);
    const found=await env.DB.prepare("SELECT id FROM audits WHERE id=?").bind(auditId).first();if(!found)return json({error:"Audit nicht gefunden"},404);
    await env.DB.prepare("INSERT INTO aw_berichttexte (audit_id,einleitung,aktualisiert_am) VALUES (?,?,datetime('now')) ON CONFLICT(audit_id) DO UPDATE SET einleitung=excluded.einleitung,aktualisiert_am=datetime('now')").bind(auditId,d.intro).run();return json({saved:true});}
 }
 if(/^\/api\/audits\/\d+\/management-summary$/.test(p)){
  const auditId=Number(p.split("/")[3]);
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS aw_management_summaries (audit_id INTEGER PRIMARY KEY, zusammenfassung TEXT NOT NULL, aktualisiert_am TEXT DEFAULT (datetime('now')))").run();
  if(req.method==="GET"){const row=await env.DB.prepare("SELECT zusammenfassung FROM aw_management_summaries WHERE audit_id=?").bind(auditId).first();return json({summary:row?.zusammenfassung??null})}
  if(req.method==="PUT"){const d=await parse(req);if(typeof d?.summary!=="string"||d.summary.length>15000)return json({error:"Ungültige Management Summary"},400);
    const found=await env.DB.prepare("SELECT id FROM audits WHERE id=?").bind(auditId).first();if(!found)return json({error:"Audit nicht gefunden"},404);
    await env.DB.prepare("INSERT INTO aw_management_summaries (audit_id,zusammenfassung,aktualisiert_am) VALUES (?,?,datetime('now')) ON CONFLICT(audit_id) DO UPDATE SET zusammenfassung=excluded.zusammenfassung,aktualisiert_am=datetime('now')").bind(auditId,d.summary).run();return json({saved:true});}
 }
 if(p==="/api/documents"||p.startsWith("/api/documents/")){
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS aw_dokumentverzeichnis (id INTEGER PRIMARY KEY AUTOINCREMENT,kunden_id INTEGER NOT NULL,name TEXT NOT NULL,version TEXT NOT NULL DEFAULT '',erstellt_am TEXT DEFAULT (datetime('now')))").run();
  const columns=(await env.DB.prepare("PRAGMA table_info(aw_dokumentverzeichnis)").all()).results;
  if(!columns.some(c=>c.name==="datum"))await env.DB.prepare("ALTER TABLE aw_dokumentverzeichnis ADD COLUMN datum TEXT NOT NULL DEFAULT ''").run();
  if(p==="/api/documents"&&req.method==="GET"){const id=Number(url.searchParams.get("client_id"));if(!id)return json([]);return json((await env.DB.prepare("SELECT id,name,version,datum FROM aw_dokumentverzeichnis WHERE kunden_id=? ORDER BY name,id").bind(id).all()).results)}
  if(p==="/api/documents"&&req.method==="POST"){const d=await parse(req),id=Number(d?.client_id);if(!id||!clean(d?.name,300).trim())return json({error:"Kunde und Dokumentname erforderlich"},400);const r=await env.DB.prepare("INSERT INTO aw_dokumentverzeichnis(kunden_id,name,datum,version) VALUES(?,?,?,?)").bind(id,clean(d.name,300).trim(),clean(d.datum,40),clean(d.version,100)).run();return json({id:r.meta.last_row_id},201)}
  if(p==="/api/documents/import"&&req.method==="POST"){const d=await parse(req),id=Number(d?.client_id),rows=d?.rows;if(!id||!Array.isArray(rows)||rows.length>1000)return json({error:"Ungültiger CSV-Import (max. 1000 Zeilen)"},400);
    const valid=rows.map(x=>({name:clean(x?.name,300).trim(),datum:clean(x?.datum,40),version:clean(x?.version,100)})).filter(x=>x.name);
    const current=(await env.DB.prepare("SELECT name,datum,version FROM aw_dokumentverzeichnis WHERE kunden_id=?").bind(id).all()).results;
    const key=x=>[x.name.toLocaleLowerCase(),x.datum,x.version].join("|"),seen=new Set(current.map(key));const fresh=valid.filter(x=>{const k=key(x);if(seen.has(k))return false;seen.add(k);return true});
    for(let i=0;i<fresh.length;i+=50)await env.DB.batch(fresh.slice(i,i+50).map(x=>env.DB.prepare("INSERT INTO aw_dokumentverzeichnis(kunden_id,name,datum,version) VALUES(?,?,?,?)").bind(id,x.name,x.datum,x.version)));
    return json({imported:fresh.length,skipped:rows.length-fresh.length});
  }
  const match=p.match(/^\/api\/documents\/(\d+)$/);
  if(match){const id=Number(match[1]),client=Number(url.searchParams.get("client_id")||0);
    if(req.method==="PUT"){const d=await parse(req);if(!client||!clean(d?.name,300).trim())return json({error:"Ungültiger Dokumenteintrag"},400);const r=await env.DB.prepare("UPDATE aw_dokumentverzeichnis SET name=?,datum=?,version=? WHERE id=? AND kunden_id=?").bind(clean(d.name,300).trim(),clean(d.datum,40),clean(d.version,100),id,client).run();return json({saved:r.meta.changes===1});}
    if(req.method==="DELETE"){const r=await env.DB.prepare("DELETE FROM aw_dokumentverzeichnis WHERE id=? AND kunden_id=?").bind(id,client).run();return json({deleted:r.meta.changes===1});}
  }
 }
 if(p==="/api/clients"){
  if(req.method==="GET"){const a=(await env.DB.prepare("SELECT * FROM kunden ORDER BY firmenname").all()).results;return json(a.map(x=>({id:String(x.id),name:x.firmenname,logo_url:x.logo_url})))}
  if(req.method==="POST"){const d=await parse(req);if(!d?.name?.trim())return json({error:"Kundenname fehlt"},400);const x=await env.DB.prepare("INSERT INTO kunden (firmenname,logo_url) VALUES (?,?)").bind(clean(d.name,200),clean(d.logo_url,1000)).run();return json({id:String(x.meta.last_row_id)},201)}
 }
 if(p==="/api/audits"){
  if(req.method==="GET"){const a=(await env.DB.prepare("SELECT a.*,k.firmenname client_name FROM audits a JOIN kunden k ON a.kunden_id=k.id ORDER BY a.id DESC").all()).results;return json(a.map(x=>({id:String(x.id),client_id:String(x.kunden_id),client_name:x.client_name,title:x.bezeichnung,year:Number((x.auditdatum||"").slice(0,4))||new Date().getFullYear(),mode:modeOf(x),auditor:x.auditor,audit_date:x.auditdatum})))}
  if(req.method==="POST"){const d=await parse(req);if(!d?.client_id)return json({error:"Kunde fehlt"},400);const title=clean((d.title||"Internes Audit")+" – "+(d.mode||"Aufrechterhaltungsaudit"),250);const date=clean(d.audit_date||String(d.year)+"-01-01",30);const x=await env.DB.prepare("INSERT INTO audits (kunden_id,bezeichnung,auditdatum,auditor,status) VALUES (?,?,?,?,?)").bind(Number(d.client_id),title,date,clean(d.auditor,200),"Offen").run();return json({id:String(x.meta.last_row_id)},201)}
 }
 if(p==="/api/questions"&&req.method==="GET"){
   const a=(await env.DB.prepare("SELECT * FROM aw_vorlagen ORDER BY sortierung,id").all()).results;
   return json(a.map((x,i)=>{let years={};try{years=JSON.parse(x.auswahljahre||"{}")}catch{}const selected=y=>years[String(y)]===1||years[String(y)]===true;return {id:x.id,category:x.kategorie,title:x.titel,reference:x.id,measure:x.massnahme,question_full:x.vollfrage||x.frage,question_maintenance:x.frage||x.vollfrage,evidence_examples:x.pruefkriterien,year_flags:years,year_2025:Number(selected(2025)),year_2026:Number(selected(2026)),year_2027:Number(selected(2027)),year_2028:Number(selected(2028)),templates:JSON.stringify(asTemplates(x.bausteine)),sort_index:x.sortierung??i}}));
 }
 if(p==="/api/planning/year"&&req.method==="POST"){
   const d=await parse(req),year=Number(d?.year),copyYear=Number(d?.copy_from);
   if(!Number.isInteger(year)||year<2025||year>2100)return json({error:"Ungültiges Auditjahr"},400);
   const a=(await env.DB.prepare("SELECT id,auswahljahre FROM aw_vorlagen").all()).results;
   const previous=String(copyYear);
   const statements=a.map(row=>{let flags={};try{flags=JSON.parse(row.auswahljahre||"{}")||{}}catch{}
     if(Object.prototype.hasOwnProperty.call(flags,String(year)))return null;
     flags[String(year)]=Number(d?.copy_from?!!flags[previous]:0);
     return env.DB.prepare("UPDATE aw_vorlagen SET auswahljahre=? WHERE id=?").bind(JSON.stringify(flags),row.id)
   }).filter(Boolean);
   for(let i=0;i<statements.length;i+=50)await env.DB.batch(statements.slice(i,i+50));
   return json({year,updated:statements.length});
 }
 if(p==="/api/planning/item"&&req.method==="PUT"){
   const d=await parse(req),year=Number(d?.year),id=clean(d?.id,50);
   if(!Number.isInteger(year)||year<2025||year>2100||!id||typeof d?.enabled!=="boolean")return json({error:"Ungültige Auswahl"},400);
   const row=await env.DB.prepare("SELECT auswahljahre FROM aw_vorlagen WHERE id=?").bind(id).first();
   if(!row)return json({error:"Prüfpunkt nicht gefunden"},404);
   let flags={};try{flags=JSON.parse(row.auswahljahre||"{}")||{}}catch{}
   flags[String(year)]=d.enabled?1:0;
   await env.DB.prepare("UPDATE aw_vorlagen SET auswahljahre=? WHERE id=?").bind(JSON.stringify(flags),id).run();
   return json({saved:true,year,id,enabled:d.enabled});
 }
 if(p==="/api/import"&&req.method==="POST")return json({error:"Import gesperrt: Vorlage zunächst gegen bestehende Daten abgleichen"},403);
 const m=p.match(/^\/api\/audits\/(\d+)\/answers$/);
 if(m){const aid=Number(m[1]);
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS aw_pruefpunkt_dokumente (audit_id INTEGER NOT NULL,control_id TEXT NOT NULL,dokument_id INTEGER,referenz TEXT NOT NULL DEFAULT '',PRIMARY KEY(audit_id,control_id))").run();
  if(req.method==="GET"){const a=(await env.DB.prepare("SELECT * FROM aw_auditpositionen WHERE audit_id=?").bind(aid).all()).results;const docs=(await env.DB.prepare("SELECT control_id,dokument_id,referenz FROM aw_pruefpunkt_dokumente WHERE audit_id=?").bind(aid).all()).results;const refs=new Map(docs.map(d=>[d.control_id,d]));return json(a.map(x=>({question_id:x.control_id,status:statusOf(x.bewertung),document:refs.get(x.control_id)?.referenz||"",doc_id:refs.get(x.control_id)?.dokument_id||null,evidence:x.nachweis,notes:x.notiz,finding:x.feststellung||x.massnahme_audit,template_index:0,in_scope:null})))}
  if(req.method==="PUT"){const d=await parse(req);if(!d?.question_id)return json({error:"Prüfpunkt fehlt"},400);
   const q=(await env.DB.prepare("SELECT * FROM aw_vorlagen WHERE id=?").bind(clean(d.question_id,50)).first());
   if(!q)return json({error:"Unbekannter Prüfpunkt"},404);
   const exists=await env.DB.prepare("SELECT id FROM aw_auditpositionen WHERE audit_id=? AND control_id=?").bind(aid,q.id).first();
   if(exists)await env.DB.prepare("UPDATE aw_auditpositionen SET bewertung=?,nachweis=?,notiz=?,feststellung=?,massnahme_audit=?,aktualisiert_am=datetime('now') WHERE id=?").bind(clean(d.status,20),clean(d.evidence),clean(d.notes),clean(d.finding),clean(d.finding),exists.id).run();
   else await env.DB.prepare("INSERT INTO aw_auditpositionen (audit_id,control_id,kategorie,titel,frage,vollfrage,pruefkriterien,massnahme,bausteine,bewertung,nachweis,notiz,feststellung,massnahme_audit,aktualisiert_am) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,datetime('now'))").bind(aid,q.id,q.kategorie,q.titel,q.frage,q.vollfrage,q.pruefkriterien,q.massnahme,q.bausteine,clean(d.status,20),clean(d.evidence),clean(d.notes),clean(d.finding),clean(d.finding)).run();
   const client=await env.DB.prepare("SELECT kunden_id FROM audits WHERE id=?").bind(aid).first();if(!client)return json({error:"Audit nicht gefunden"},404);
   const docId=d.doc_id?Number(d.doc_id):null;
   if(docId){const match=await env.DB.prepare("SELECT id FROM aw_dokumentverzeichnis WHERE id=? AND kunden_id=?").bind(docId,client.kunden_id).first();if(!match)return json({error:"Dokument gehört nicht zum Kunden"},400)}
   await env.DB.prepare("INSERT INTO aw_pruefpunkt_dokumente(audit_id,control_id,dokument_id,referenz) VALUES(?,?,?,?) ON CONFLICT(audit_id,control_id) DO UPDATE SET dokument_id=excluded.dokument_id,referenz=excluded.referenz").bind(aid,q.id,docId,clean(d.document,1000)).run();
   return json({saved:true});
  }
 }
 return json({error:"Nicht gefunden"},404)
 }catch(e){return json({error:"Datenbankfehler",detail:clean(e.message,300)},500)}
}
