el('word').onclick=()=>{if(!active)return;const qs=scope();const reportBody=el('report-body').innerHTML,results=el('report-stats').innerHTML;const header='<div style="border-bottom:2px solid #284c3d;margin-bottom:20px;padding-bottom:12px"><p style="font-size:12px;color:#536a5f;letter-spacing:2px">goSecurity AG · Interner Auditbericht</p><h1 style="font-family:Georgia,serif;color:#25483a;font-size:28pt">'+esc(active.title||'Internes Audit')+'</h1><h2>'+esc(active.client_name||'')+'</h2></div>';const css='<style>body{font-family:Arial,sans-serif;font-size:10pt;color:#253d32;line-height:1.55;margin:2cm}h1,h2,h3{color:#25483a}h3{margin-top:22px;border-bottom:1px solid #dce4db;padding-bottom:6px}table{border-collapse:collapse;width:100%;margin:12px 0}td,th{border:1px solid #dde5dd;padding:8px;text-align:left}.reportItem{padding:13px 0;border-bottom:1px solid #e4e9e3}.reportItem p{white-space:pre-line}.pill{font-size:9pt;color:#255e42}div.report-meta{display:grid;grid-template-columns:1fr 1fr}div.report-intro{white-space:pre-line}</style>';const content='<!doctype html><html><head><meta charset="utf-8">'+css+'</head><body>'+header+'<h3>Auditangaben</h3>'+el('report-meta').innerHTML+'<h3>Einleitung</h3><p style="white-space:pre-line">'+esc(el('report-intro-editor').value)+'</p><h3>Management Summary</h3><p style="white-space:pre-line">'+esc(el('summary-editor').value)+'</p><h3>Ergebnisübersicht</h3>'+results+'<h3>Feststellungen und Nachweise</h3>'+reportBody+'</body></html>';const blob=new Blob(['\ufeff',content],{type:'application/msword;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Auditbericht_'+String(active.client_name||'Kunde').replace(/[^a-zA-Z0-9_-]/g,'_')+'_'+active.year+'.doc';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)};
el('csv').onclick=csv;el('backup').onclick=backup;el('add-document').onclick=async()=>{if(!active)return alert('Bitte zuerst ein Audit auswählen');const name=prompt('Dokumentname:');if(!name?.trim())return;const datum=prompt('Datum (optional):','')||'';const version=prompt('Version (optional):','')||'';try{await api('/api/documents','POST',{client_id:active.client_id,name,datum,version});await fetchDocuments();renderDocuments()}catch(e){alertStatus(e.message,true)}};el('doc-file').onchange=async e=>{if(!active)return alert('Bitte zuerst ein Audit wählen');const file=e.target.files[0];if(!file)return;try{const rows=parseCSV(await file.text());if(!rows.length)throw Error('CSV ist leer');const headings=rows[0].map(x=>x.trim().toLowerCase()),nameCol=headings.findIndex(x=>/dokument|name|titel/.test(x)),dateCol=headings.findIndex(x=>/datum|date/.test(x)),versionCol=headings.findIndex(x=>/version|stand/.test(x));const hasHead=nameCol>=0;const items=(hasHead?rows.slice(1):rows).map(r=>({name:r[hasHead?nameCol:0]||'',datum:r[hasHead&&dateCol>=0?dateCol:1]||'',version:r[hasHead&&versionCol>=0?versionCol:2]||''})).filter(r=>r.name.trim());if(!confirm(items.length+' Dokumente aus CSV importieren? Vorhandene identische Einträge werden übersprungen.'))return;const result=await api('/api/documents/import','POST',{client_id:active.client_id,rows:items});await fetchDocuments();renderDocuments();el('doc-import-status').textContent=result.imported+' importiert · '+result.skipped+' übersprungen'}catch(err){el('doc-import-status').textContent=err.message;alertStatus(err.message,true)}finally{e.target.value=''}};
el('add-client').onclick=async()=>{try{await api('/api/clients','POST',{name:el('client-name').value,logo_url:el('client-logo').value});el('client-name').value='';await load()}catch(e){alertStatus(e.message,true)}};
el('add-audit').onclick=async()=>{try{await api('/api/audits','POST',{client_id:el('client-select').value,title:el('audit-title').value,year:Number(el('audit-year').value),mode:el('audit-mode').value,auditor:el('auditor').value,audit_date:el('audit-date').value});await load();go('overview')}catch(e){alertStatus(e.message,true)}};
el('plan-year').onchange=e=>{planningYear=Number(e.target.value);renderPlanning()};['plan-search','plan-area'].forEach(id=>el(id).addEventListener('input',renderPlanning));el('add-year').onclick=async()=>{const input=prompt('Neues Auditjahr eingeben (z.B. 2029):',String(Math.max(...yearList())+1));if(input===null)return;const year=Number(input);if(!Number.isInteger(year)||year<2025||year>2100){alert('Ungültiges Auditjahr');return}if(yearList().includes(year)){planningYear=year;renderPlanning();return}try{await api('/api/planning/year','POST',{year});await load();planningYear=year;go('planning')}catch(e){alertStatus(e.message,true)}};el('copy-year').onclick=async()=>{const source=Number(prompt('Auditumfang von welchem Jahr übernehmen?',String(planningYear-1)));if(!yearList().includes(source))return alert('Jahr nicht gefunden');if(!confirm('Den Umfang von '+source+' nach '+planningYear+' kopieren? Bereits bestehende Zuordnungen bleiben unverändert.'))return;try{const result=await api('/api/planning/year','POST',{year:planningYear,copy_from:source});if(result.updated===0)return alert('Für dieses Jahr sind bereits Einträge vorhanden. Bitte einzelne Prüfpunkte anpassen.');await load();go('planning')}catch(e){alertStatus(e.message,true)}};
